Given an array arr[] of integers, find the Next Smaller Element (NSE) for each element in the array.The Next Smaller Element of an element x is defined as the first element to the right of x in the array that is strictly smaller than x.If no such element exists for a particular position, the NSE should be considered as -1.Examples:Input: arr[] = [4, 8, 5, 2, 25]Output: [2, 5, 2, -1, -1]Explanation: The first element smaller than 4 having index > 0 is 2.The first element smaller than 8 having index > 1 is 5.The first element smaller than 5 having index > 2 is 2.There are no elements smaller than 2 having index > 3.There are no elements smaller than 25 having index > 4.Input: arr[] = [13, 7, 6, 12]Output: [7, 6, -1, -1]Explanation: The first element smaller than 13 having index > 0 is 7.The first element smaller than 7 having index > 1 is 6.There are no elements smaller than 6 having index > 2.There are no elements smaller than 12 having index > 3.Try It YourselfTable of Content[Naive Approach] Using Nested loops - O(n^2) Time O(1) Space[Expected Approach] Using Monotonic Stack - O(n) Time O(n) Space[Naive Approach] Using Nested loops - O(n2) Time O(1) SpaceThe idea is to check the next smaller element for every element using a nested loop. For each element, we look at all elements to its right until we find a smaller one. If no such element exists, we store -1.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> nextSmallerEle(vector<int>& arr) {
    int n = arr.size();

    // initialize all NSEs as -1
    vector<int> result(n, -1); 

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[i]) {

                // first smaller element on the right
                result[i] = arr[j]; 
                break;
            }
        }
    }

    return result;
}

int main() {
    vector<int> arr = {4, 8, 5, 2, 25};
    vector<int> nse = nextSmallerEle(arr);

    for (int x : nse) {
        cout << x << " ";
    }
    cout << endl;

    return 0;
}


